function prefixCounts(words, queries) {
  const root = { count: 0, next: new Map() }
  for (const word of words) {
    let node = root
    node.count++
    for (const ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, { count: 0, next: new Map() })
      node = node.next.get(ch)
      node.count++
    }
  }
  return queries.map(query => {
    let node = root
    for (const ch of query) {
      node = node.next.get(ch)
      if (!node) return 0
    }
    return node.count
  })
}

solution.py:
def prefix_counts(words, queries):
    root = {"count": 0, "next": {}}
    for word in words:
        node = root
        node["count"] += 1
        for ch in word:
            node = node["next"].setdefault(ch, {"count": 0, "next": {}})
            node["count"] += 1

    def lookup(query):
        node = root
        for ch in query:
            node = node["next"].get(ch)
            if node is None:
                return 0
        return node["count"]

    return [lookup(query) for query in queries]
